-- Giải thích: GENERATED ALWAYS AS IDENTITY chặn ứng dụng tự điền id (muốn ép phải viết OVERRIDING SYSTEM VALUE).
--   BY DEFAULT thì cho điền tay, dễ làm lệch sequence. UNIQUE trên email tự tạo index. DEFAULT now() cho created_at.
-- Bẫy: dùng serial (kiểu cũ, sequence tách rời bảng, quyền riêng) hoặc GENERATED BY DEFAULT (không chặn điền tay).
CREATE TABLE f09.customers (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL UNIQUE,
  full_name  text NOT NULL,
  phone      text,
  created_at timestamptz NOT NULL DEFAULT now()
);
